import{_ as h,c as t,o as n,b as i}from"./chunks/framework.CDs6etjB.js";const c=JSON.parse('{"title":"Thống nhất spec trước khi hợp nhất 2 hệ thống và bài học từ dự án LINE × Yahoo","description":"Trong giai đoạn đầu dự án hợp nhất ShortURL của LINE và Yahoo, team đã chốt spec, đối chiếu tài liệu với code thực tế và xử lý các phần bị bỏ sót để giảm rủi ro khi triển khai.","frontmatter":{"footer":true,"title":"Thống nhất spec trước khi hợp nhất 2 hệ thống và bài học từ dự án LINE × Yahoo","description":"Trong giai đoạn đầu dự án hợp nhất ShortURL của LINE và Yahoo, team đã chốt spec, đối chiếu tài liệu với code thực tế và xử lý các phần bị bỏ sót để giảm rủi ro khi triển khai.","authors":["lethanh"],"date":"2026-06-07T00:00:00.000Z","outline":"deep","draft":false},"headers":[{"level":2,"title":"Thách thức khi thống nhất spec","slug":"thach-thuc-khi-thong-nhat-spec","link":"#thach-thuc-khi-thong-nhat-spec","children":[{"level":3,"title":"Cách chúng tôi giải quyết thách thức này","slug":"cach-chung-toi-giai-quyet-thach-thuc-nay","link":"#cach-chung-toi-giai-quyet-thach-thuc-nay","children":[]}]},{"level":2,"title":"Chốt spec trước khi bắt tay triển khai","slug":"chot-spec-truoc-khi-bat-tay-trien-khai","link":"#chot-spec-truoc-khi-bat-tay-trien-khai","children":[]},{"level":2,"title":"Những phần vẫn bị bỏ sót (và bài học rút ra)","slug":"nhung-phan-van-bi-bo-sot-va-bai-hoc-rut-ra","link":"#nhung-phan-van-bi-bo-sot-va-bai-hoc-rut-ra","children":[]},{"level":2,"title":"Kết luận","slug":"ket-luan","link":"#ket-luan","children":[]}],"relativePath":"blog/2026-06-07-thong-nhat-spect-truoc-khi-hop-nhat-2-he-thong.md","filePath":"blog/2026-06-07-thong-nhat-spect-truoc-khi-hop-nhat-2-he-thong.md","lastUpdated":1780835152000}');const a=h({name:"blog/2026-06-07-thong-nhat-spect-truoc-khi-hop-nhat-2-he-thong.md"},[["render",function(h,c,a,o,l,e){return n(),t("div",null,[...c[0]||(c[0]=[i('<p>Xin chào mọi người! Trong bài này, mình tiếp tục chia sẻ về dự án hợp nhất 2 hệ thống thành một, với chủ đề quan trọng nhất ở giai đoạn đầu: <strong>thống nhất spec trước khi bắt tay triển khai</strong>.</p><p>Bài viết tập trung vào 3 ý chính:</p><ul><li>Vì sao phải chốt spec sớm.</li><li>Team đã làm gì để giảm rủi ro bỏ sót.</li><li>Những điểm vẫn có thể sai lệch dù đã review kỹ.</li></ul><nav class="table-of-contents"><ul><li><a href="#thach-thuc-khi-thong-nhat-spec">Thách thức khi thống nhất spec</a><ul><li><a href="#cach-chung-toi-giai-quyet-thach-thuc-nay">Cách chúng tôi giải quyết thách thức này</a></li></ul></li><li><a href="#chot-spec-truoc-khi-bat-tay-trien-khai">Chốt spec trước khi bắt tay triển khai</a></li><li><a href="#nhung-phan-van-bi-bo-sot-va-bai-hoc-rut-ra">Những phần vẫn bị bỏ sót (và bài học rút ra)</a></li><li><a href="#ket-luan">Kết luận</a></li></ul></nav><h1 id="vi-sao-phai-thong-nhat-spec-truoc-khi-hop-nhat" tabindex="-1">Vì sao phải thống nhất spec trước khi hợp nhất? <a class="header-anchor" href="#vi-sao-phai-thong-nhat-spec-truoc-khi-hop-nhat" aria-label="Permalink to &quot;Vì sao phải thống nhất spec trước khi hợp nhất?&quot;">​</a></h1><p>Trước khi bắt đầu hợp nhất 2 hệ thống, chúng tôi xác định rằng việc thống nhất <strong>spec</strong> là bắt buộc. Spec mô tả chi tiết cách hệ thống vận hành: thành phần, giao diện, luồng xử lý và các yêu cầu kỹ thuật.</p><p>Cả ShortURL của LINE và Yahoo đều có phần chung và phần riêng. Vì vậy, chúng tôi phải quyết định rõ:</p><ul><li>Spec nào được giữ nguyên.</li><li>Spec nào cần loại bỏ.</li><li>Spec nào cần chỉnh sửa để phù hợp với hệ thống mới.</li></ul><p>Ngoài ra, LYMIX cũng có các spec mới, nên cần thống nhất luôn từ đầu để tránh vênh giữa các team khi triển khai.</p><p>Thực tế, dù đã dành khoảng 3 tuần thảo luận giữa team LINE JP, Yahoo JP và team Việt Nam, vẫn có những điểm bị bỏ sót. Phần dưới mình chia sẻ cụ thể.</p><h2 id="thach-thuc-khi-thong-nhat-spec" tabindex="-1">Thách thức khi thống nhất spec <a class="header-anchor" href="#thach-thuc-khi-thong-nhat-spec" aria-label="Permalink to &quot;Thách thức khi thống nhất spec&quot;">​</a></h2><p>Việc thống nhất spec đặt ra nhiều thách thức.</p><p><strong>Thách thức lớn nhất</strong> là cả hai dự án ShortURL của LINE và Yahoo đều đã hơn 10 năm tuổi.</p><p>Nhân sự thay đổi nhiều qua thời gian. Dù tài liệu của phía Nhật khá kỹ, nhưng không thể tin tài liệu 100% nếu không đối chiếu với hệ thống đang chạy thực tế.</p><p>Một điểm nữa là cách viết spec thường theo từng mảng, không phải lúc nào cũng đi theo một luồng từ A-Z.</p><p>Vì vậy, việc đọc hiểu và cập nhật spec rất dễ sai sót. Dự án càng lâu năm, tài liệu càng phức tạp, người cập nhật sau càng dễ bỏ qua phần quan trọng.</p><p>Theo trải nghiệm cá nhân của mình khi làm việc với một team Hàn trước đây, tài liệu của họ thường có luồng rõ ràng hơn và nhiều minh họa hơn, nên việc đọc và cập nhật dễ hơn đáng kể.</p><p>Vì vậy, một trong những thách thức lớn nhất của chúng tôi là <strong>hiểu đầy đủ toàn bộ spec hiện tại của cả 2 hệ thống cũ</strong>.</p><h3 id="cach-chung-toi-giai-quyet-thach-thuc-nay" tabindex="-1">Cách chúng tôi giải quyết thách thức này <a class="header-anchor" href="#cach-chung-toi-giai-quyet-thach-thuc-nay" aria-label="Permalink to &quot;Cách chúng tôi giải quyết thách thức này&quot;">​</a></h3><p>Để xử lý, chúng tôi làm theo 4 bước:</p><ol><li>Tìm lại những người từng tham gia dự án và vẫn còn trong công ty để hỏi các lưu ý quan trọng.</li><li>Đọc code hiện tại, đối chiếu với spec để tìm điểm lệch và phần thiếu.</li><li>Tạo bản spec hợp nhất từ 2 hệ thống, sau đó chỉnh sửa theo thực tế vận hành.</li><li>Review chéo với tất cả bên liên quan để chốt bản cuối cùng.</li></ol><h2 id="chot-spec-truoc-khi-bat-tay-trien-khai" tabindex="-1">Chốt spec trước khi bắt tay triển khai <a class="header-anchor" href="#chot-spec-truoc-khi-bat-tay-trien-khai" aria-label="Permalink to &quot;Chốt spec trước khi bắt tay triển khai&quot;">​</a></h2><p>Sau khi hiểu rõ spec của hệ thống cũ, chúng tôi chốt bản hợp nhất cho LYMIX.</p><p>Trong đó xác định rõ:</p><ul><li>Giữ lại tính năng nào của LINE.</li><li>Giữ lại tính năng nào của Yahoo.</li><li>Spec mới nào sẽ thêm.</li><li>Tính năng nào dừng phát triển mới nhưng vẫn phải tương thích ngược.</li></ul><p>Ví dụ: không hỗ trợ tạo ShortURL mới theo kiểu cũ, nhưng vẫn phải hỗ trợ redirect cho các ShortURL đã tạo trước đó.</p><p>Việc chốt spec giúp team có phạm vi rõ ràng, giảm tranh luận khi triển khai và hạn chế bỏ sót lớn.</p><h2 id="nhung-phan-van-bi-bo-sot-va-bai-hoc-rut-ra" tabindex="-1">Những phần vẫn bị bỏ sót (và bài học rút ra) <a class="header-anchor" href="#nhung-phan-van-bi-bo-sot-va-bai-hoc-rut-ra" aria-label="Permalink to &quot;Những phần vẫn bị bỏ sót (và bài học rút ra)&quot;">​</a></h2><p>Dù làm kỹ, vẫn có những điểm chỉ lộ ra khi bắt đầu triển khai, thậm chí sát ngày phát hành.</p><ol><li><strong>Dựng spec từ code cũ vẫn có thể thiếu</strong><ul><li>Code 10-15 năm tuổi đã qua nhiều lần chỉnh sửa, thư viện và framework cũ, nên rất khó khôi phục đầy đủ ý đồ ban đầu.</li></ul></li><li><strong>Cấu hình Kubernetes có thể ảnh hưởng trực tiếp tới logic</strong><ul><li>Một số hành vi không nằm trong code mà nằm ở cấu hình router/ingress.</li></ul><details class="details custom-block"><summary>Chi tiết</summary><p>Chúng tôi gặp một trường hợp phía Yahoo ghi đè host ở tầng Kubernetes. Ban đầu hệ thống chỉ hỗ trợ 1 domain; khi cần mở rộng nhiều domain, họ xử lý bằng cách ghi đè host thay vì sửa code. Nếu chỉ đọc code mà không rà cấu hình deploy, rất dễ bỏ sót trường hợp này. Rất may đã phát hiện ra trước khi deploy, nếu không sẽ rất khó debug sau này và ảnh hưởng lớn đến người dùng.</p></details></li><li><strong>Logic có thể xung đột khi chạy thực tế</strong><ul><li>Có những điểm nhìn trên tài liệu là hợp lý nhưng khi ghép luồng thật thì xung đột, buộc phải điều chỉnh lại spec theo thực tế.</li></ul></li></ol><h2 id="ket-luan" tabindex="-1">Kết luận <a class="header-anchor" href="#ket-luan" aria-label="Permalink to &quot;Kết luận&quot;">​</a></h2><p>Chốt spec sớm là điều kiện bắt buộc để hợp nhất 2 hệ thống an toàn, nhưng chưa đủ để loại bỏ toàn bộ rủi ro.</p><p>Bài học quan trọng nhất của chúng tôi là: <strong>review spec + đối chiếu code + kiểm tra cấu hình môi trường triển khai</strong> phải đi cùng nhau.</p>',33)])])}]]);export{c as __pageData,a as default};
